const { chromium } = require('/tmp/gnhf-pw/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });
  const widths = [1280, 1100, 1024, 900, 721];
  for (const w of widths) {
    const page = await browser.newPage({ viewport: { width: w, height: 800 } });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'networkidle' });
    await page.evaluate(() => {
      try { localStorage.setItem('simplify-viewer-tour-v1', '1'); } catch {}
      const tour = document.getElementById('uiTour');
      if (tour) { tour.hidden = true; tour.style.display = 'none'; }
    });
    const measure = async (label) => page.evaluate((label) => {
      const header = document.querySelector('header');
      const form = document.querySelector('.upload-form');
      const baseline = document.querySelector('.header-baseline');
      const fields = [...document.querySelectorAll('.header-baseline .baseline-field--inline')]
        .filter(el => !el.hidden)
        .map(el => ({
          text: el.textContent.replace(/\s+/g, ' ').trim().slice(0, 40),
          top: Math.round(el.getBoundingClientRect().top),
          height: Math.round(el.getBoundingClientRect().height),
        }));
      const pills = [...document.querySelectorAll('#headerBaselineAlgoRow .baseline-algo-pill')].map(b => ({
        text: b.textContent.trim(),
        pressed: b.getAttribute('aria-pressed'),
        title: b.getAttribute('title') || '',
      }));
      const formRect = form.getBoundingClientRect();
      const kids = [...form.children].map(el => {
        const r = el.getBoundingClientRect();
        return { tag: el.id || el.className?.toString?.().slice(0,30) || el.tagName, top: Math.round(r.top), left: Math.round(r.left), w: Math.round(r.width), h: Math.round(r.height) };
      });
      // group by row (top within 8px)
      const rows = [];
      for (const k of kids) {
        let row = rows.find(r => Math.abs(r.top - k.top) < 8);
        if (!row) { row = { top: k.top, items: [] }; rows.push(row); }
        row.items.push(k.tag);
      }
      return {
        label,
        headerH: Math.round(header.getBoundingClientRect().height),
        formH: Math.round(formRect.height),
        baselineH: Math.round(baseline.getBoundingClientRect().height),
        scrollW: document.documentElement.scrollWidth,
        clientW: document.documentElement.clientWidth,
        formRows: rows.length,
        rowItems: rows.map(r => r.items),
        visibleFields: fields,
        pills,
      };
    }, label);
    const before = await measure('none');
    await page.click('#headerBaselineAlgoRow [data-algo="dots"]');
    const dots = await measure('dots');
    await page.click('#headerBaselineAlgoRow [data-algo="dp"]');
    const both = await measure('dots+dp');
    await page.click('#headerBaselineAlgoRow [data-algo="squish"]');
    const all = await measure('all3');
    console.log(JSON.stringify({ width: w, before, dots, both, all }, null, 2));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
