const { chromium } = require('/tmp/gnhf-pw/node_modules/playwright');
const path = require('path');
const root = '/Users/sinchunyeung/github/simplification-of-trajectory-streams';

(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });

  // Fixture
  {
    const page = await browser.newPage({ viewport: { width: 900, height: 720 } });
    await page.goto('file://' + path.join(root, 'web/usability/desktop-compare-bar-wrap.html'));
    await page.screenshot({ path: path.join(root, 'web/usability/desktop-compare-bar-wrap.png'), fullPage: true });
    await page.close();
  }

  async function prep(page) {
    await page.evaluate(() => {
      try { localStorage.setItem('simplify-viewer-tour-v1', '1'); } catch {}
      const tour = document.getElementById('uiTour');
      if (tour) { tour.hidden = true; tour.style.display = 'none'; }
    });
  }

  async function shot(width, height, name, selectAll) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'networkidle' });
    await prep(page);
    if (selectAll) {
      for (const algo of ['dots', 'dp', 'squish']) {
        await page.click(`#headerBaselineAlgoRow [data-algo="${algo}"]`);
      }
    }
    const metrics = await page.evaluate(() => {
      const header = document.querySelector('header');
      const load = document.getElementById('loadBtn');
      const baseline = document.querySelector('.header-baseline');
      const status = document.getElementById('statusGrid');
      return {
        headerH: Math.round(header.getBoundingClientRect().height),
        loadTop: Math.round(load.getBoundingClientRect().top),
        baselineTop: Math.round(baseline.getBoundingClientRect().top),
        compareLabel: document.querySelector('.header-baseline-label')?.textContent,
        titles: [...document.querySelectorAll('#headerBaselineAlgoRow .baseline-algo-pill')].every(b => !!b.title),
        scrollW: document.documentElement.scrollWidth,
        clientW: document.documentElement.clientWidth,
        statusText: status?.innerText?.replace(/\s+/g, ' ').trim() || '',
      };
    });
    await page.locator('header').screenshot({ path: path.join(root, 'web/usability', name) });
    await page.close();
    return metrics;
  }

  const results = {};
  results.idle1280 = await shot(1280, 800, 'desktop-compare-bar-wrap-1280-idle-live.png', false);
  results.all1280 = await shot(1280, 800, 'desktop-compare-bar-wrap-1280-live.png', true);
  results.all900 = await shot(900, 800, 'desktop-compare-bar-wrap-900-live.png', true);
  results.all721 = await shot(721, 800, 'desktop-compare-bar-wrap-721-live.png', true);
  results.all390 = await shot(390, 844, 'desktop-compare-bar-wrap-390-live.png', true);

  // Status gloss check after load at 1280
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
