      indices: document.getElementById('statusIndices')?.innerText?.replace(/\s+/g, ' ').trim(),
      grid: document.getElementById('statusGrid')?.innerText?.replace(/\s+/g, ' ').trim(),
      openTitle: document.querySelector('#statusGrid span[title]')?.getAttribute('title') || '',
